/**
 * /image-gallery/
 *
 * NO `// GENERATED by scripts/gen-pages.mjs` MARKER, deliberately.
 * gen-pages.mjs overwrites any page file whose content starts with that line,
 * so leaving it here would mean the next `npm run gen:pages` silently destroys
 * this page. Removing it is what puts the file on the script's `kept:` list.
 * Same call, for the same reason, as hair-loss-treatment-in-bangalore.tsx and
 * home.tsx.
 *
 * PagePlaceholder is not used either: it renders `seoFor(slug).h1`, which would
 * be a SECOND <h1> under the one PageBanner already emits. verify-gallery.mjs
 * fails on that.
 *
 * The h1 itself is the captured string from src/seo/pages.ts, verbatim, down to
 * the typographic apostrophe in "What's" (U+2019). It lives in
 * content/gallery/image-gallery.ts.
 */
import ImageGalleryPage from '../components/gallery/ImageGalleryPage'

export default function ImageGallery() {
  return <ImageGalleryPage />
}
